//! The priority-layered LED manager and the tilt monitor.
#![no_std]

use core::cell::RefCell;
use core::ffi::c_void;
use core::sync::atomic::{AtomicBool, AtomicU32, Ordering};

use critical_section::Mutex;
use ohf_sys::{
    sl_led_rgb_pwm_t, sl_led_set_rgb_color, sl_led_t, sl_led_turn_off, sl_led_turn_on,
    sl_sleeptimer_start_periodic_timer_ms, sl_sleeptimer_timer_handle_t, SyncCell, ZERO_TIMER,
};

// Generated by build.rs from the manifest config
include!(concat!(env!("OUT_DIR"), "/config.rs"));

#[derive(Clone, Copy)]
pub struct Rgb {
    pub r: u16,
    pub g: u16,
    pub b: u16,
}

impl Rgb {
    pub const fn rgb8(r: u8, g: u8, b: u8) -> Self {
        Self { r: r as u16 * 257, g: g as u16 * 257, b: b as u16 * 257 }
    }

    // `brightness` is 0-65535
    fn scaled(self, brightness: u32) -> Self {
        let scale = |c: u16| ((c as u32 * brightness) / 65535) as u16;
        Self { r: scale(self.r), g: scale(self.g), b: scale(self.b) }
    }
}

pub mod color {
    use super::Rgb;

    pub const BLACK: Rgb = Rgb::rgb8(0, 0, 0);
    pub const WHITE_DIM: Rgb = Rgb::rgb8(75, 75, 75);
    pub const RESET_RED: Rgb = Rgb::rgb8(255, 0, 0);
    pub const RESET_ORANGE: Rgb = Rgb::rgb8(255, 40, 0);
    pub const SEARCH_BLUE: Rgb = Rgb::rgb8(0, 0, 75);
    pub const JOIN_GREEN: Rgb = Rgb::rgb8(0, 255, 0);
}

/// Higher layers hide lower ones while active
#[derive(Clone, Copy)]
pub enum Priority {
    /// Network state
    Background,
    /// User command or Zigbee light state
    Manual,
    /// Short feedback, such as joining or identify
    Notification,
    Tilt,
    /// Factory reset button
    Reset,
}

impl Priority {
    const COUNT: usize = Priority::Reset as usize + 1;
}

#[derive(Clone, Copy)]
enum Mode {
    Off,
    Static,
    /// On/off square wave
    Blink { period_ms: u16 },
    /// Triangle wave fading between two brightnesses (0-65535)
    Pulse { period_ms: u16, brightness_min: u16, brightness_max: u16 },
}

#[derive(Clone, Copy)]
pub struct Pattern {
    mode: Mode,
    color: Rgb,
    /// Clear the layer after this long
    duration_ms: Option<u32>,
}

impl Pattern {
    pub const OFF: Self = Self { mode: Mode::Off, color: color::BLACK, duration_ms: None };

    pub const fn solid(color: Rgb) -> Self {
        Self { mode: Mode::Static, color, duration_ms: None }
    }

    pub const fn blink(color: Rgb, period_ms: u16) -> Self {
        assert!(period_ms >= 2);
        Self { mode: Mode::Blink { period_ms }, color, duration_ms: None }
    }

    pub const fn pulse(color: Rgb, period_ms: u16, brightness_min: u16, brightness_max: u16) -> Self {
        assert!(period_ms >= 2 && brightness_min <= brightness_max);
        Self {
            mode: Mode::Pulse { period_ms, brightness_min, brightness_max },
            color,
            duration_ms: None,
        }
    }

    pub const fn lasting(self, duration_ms: u32) -> Self {
        Self { duration_ms: Some(duration_ms), ..self }
    }

    /// The color `elapsed_ms` into the pattern, `None` for off
    fn color_at(&self, elapsed_ms: u32) -> Option<Rgb> {
        match self.mode {
            Mode::Off => None,
            Mode::Static => Some(self.color),
            Mode::Blink { period_ms } => {
                let period = period_ms as u32;
                (elapsed_ms % period < period / 2).then_some(self.color)
            }
            Mode::Pulse { period_ms, brightness_min, brightness_max } => {
                let period = period_ms as u32;
                let half = period / 2;
                let phase = elapsed_ms % period;
                let triangle = if phase < half {
                    phase * 65535 / half
                } else {
                    65535 - (phase - half) * 65535 / (period - half)
                };
                let (min, max) = (brightness_min as u32, brightness_max as u32);
                Some(self.color.scaled(min + (max - min) * triangle / 65535))
            }
        }
    }
}

// ~100 ms
const TILT_CHECK_TICKS: u32 = 25;

// The network search pulse
const SEARCH_PULSE_PERIOD_MS: u16 = 2760;
const SEARCH_PULSE_MIN_BRIGHTNESS: u16 = 6554; // ~10%

extern "C" {
    static sl_led_ws2812: sl_led_rgb_pwm_t;
    fn ws2812_led_driver_refresh();
}

#[derive(Clone, Copy)]
struct Layer {
    pattern: Pattern,
    start_tick: u32,
}

impl Layer {
    // Elapsed ticks rather than an absolute expiry, so the tick counter may wrap
    fn elapsed_ticks(&self, tick: u32) -> u32 {
        tick.wrapping_sub(self.start_tick)
    }

    fn expired(&self, tick: u32) -> bool {
        self.pattern
            .duration_ms
            .is_some_and(|ms| self.elapsed_ticks(tick) >= ms / LED_EFFECTS_UPDATE_INTERVAL_MS)
    }
}

struct Layers([Option<Layer>; Priority::COUNT]);

impl Layers {
    fn set(&mut self, priority: Priority, pattern: Pattern, tick: u32) {
        self.0[priority as usize] = Some(Layer { pattern, start_tick: tick });
    }

    fn clear(&mut self, priority: Priority) {
        self.0[priority as usize] = None;
    }

    /// Retires expired layers and returns the highest remaining one
    fn top(&mut self, tick: u32) -> Option<Layer> {
        for slot in &mut self.0 {
            if slot.is_some_and(|layer| layer.expired(tick)) {
                *slot = None;
            }
        }
        self.0.iter().rev().flatten().next().copied()
    }
}

struct Tilt {
    monitoring: bool,
    tilted: bool,
}

// Also used from the sleeptimer ISRs
static LAYERS: Mutex<RefCell<Layers>> = Mutex::new(RefCell::new(Layers([None; Priority::COUNT])));
static GLOBAL_TICK: AtomicU32 = AtomicU32::new(0);
static UPDATE_NEEDED: AtomicBool = AtomicBool::new(false);
static TILT_CHECK_DUE: AtomicBool = AtomicBool::new(false);
static MANAGER_INITIALIZED: AtomicBool = AtomicBool::new(false);
static LED_TIMER: SyncCell<sl_sleeptimer_timer_handle_t> = SyncCell::new(ZERO_TIMER);

// Network state changes can come from an ISR
static TILT: Mutex<RefCell<Tilt>> = Mutex::new(RefCell::new(Tilt { monitoring: false, tilted: false }));

fn led_common() -> *const sl_led_t {
    unsafe { &sl_led_ws2812.led_common as *const sl_led_t }
}

fn set_rgb(color: Rgb) {
    unsafe {
        sl_led_set_rgb_color(&sl_led_ws2812, color.r, color.g, color.b);
        sl_led_turn_on(led_common());
    }
}

fn turn_off() {
    unsafe { sl_led_turn_off(led_common()) }
}

extern "C" fn led_timer_callback(_handle: *mut sl_sleeptimer_timer_handle_t, _data: *mut c_void) {
    let tick = GLOBAL_TICK.fetch_add(1, Ordering::SeqCst) + 1;
    UPDATE_NEEDED.store(true, Ordering::SeqCst);
    if tick % TILT_CHECK_TICKS == 0 {
        TILT_CHECK_DUE.store(true, Ordering::SeqCst);
    }
    unsafe { ws2812_led_driver_refresh() }
}

fn update_led_hardware() {
    let color = critical_section::with(|cs| {
        // Read in the critical section, so a layer can't start after `tick`
        let tick = GLOBAL_TICK.load(Ordering::SeqCst);
        let layer = LAYERS.borrow(cs).borrow_mut().top(tick)?;
        let elapsed_ms = layer.elapsed_ticks(tick).wrapping_mul(LED_EFFECTS_UPDATE_INTERVAL_MS);
        layer.pattern.color_at(elapsed_ms)
    });

    match color {
        Some(color) => set_rgb(color),
        None => turn_off(),
    }
}

fn manager_init() {
    if MANAGER_INITIALIZED.swap(true, Ordering::SeqCst) {
        return;
    }
    unsafe {
        sl_sleeptimer_start_periodic_timer_ms(
            LED_TIMER.get(),
            LED_EFFECTS_UPDATE_INTERVAL_MS,
            Some(led_timer_callback),
            core::ptr::null_mut(),
            0,
            0,
        );
    }
}

// Registered by the led_effects_base component as a process action. The tilt check reads
// the accelerometer over I2C, so it runs here rather than in the timer ISR.
#[no_mangle]
pub extern "C" fn led_manager_process_action() {
    if TILT_CHECK_DUE.swap(false, Ordering::SeqCst) {
        check_tilt();
    }
    if UPDATE_NEEDED.swap(false, Ordering::SeqCst) {
        update_led_hardware();
    }
}

pub fn set_pattern(priority: Priority, pattern: Pattern) {
    critical_section::with(|cs| {
        let tick = GLOBAL_TICK.load(Ordering::SeqCst);
        LAYERS.borrow(cs).borrow_mut().set(priority, pattern, tick);
    });
}

pub fn clear_pattern(priority: Priority) {
    critical_section::with(|cs| LAYERS.borrow(cs).borrow_mut().clear(priority));
}

pub fn set_color(priority: Priority, color: Rgb) {
    set_pattern(priority, Pattern::solid(color));
}

// `asin(|horizontal| / |total|) > threshold`, compared as squared sines to avoid the
// trigonometry. Both sides are monotonic over 0-90 degrees.
fn is_tilted(threshold_sin2: f32) -> bool {
    let [ax, ay, az] = ohf_qma6100p::read_acceleration();
    let horizontal = ax * ax + ay * ay;
    let total = horizontal + az * az;
    total >= 0.01 && horizontal > threshold_sin2 * total
}

fn check_tilt() {
    let threshold = critical_section::with(|cs| {
        let tilt = TILT.borrow(cs).borrow();
        match (tilt.monitoring, tilt.tilted) {
            (false, _) => None,
            (true, false) => Some(LED_EFFECTS_TILT_THRESHOLD_SIN2),
            (true, true) => Some(LED_EFFECTS_TILT_RELEASE_SIN2),
        }
    });
    let Some(threshold) = threshold else {
        return;
    };

    // Not in the critical section, since I2C takes a while
    let tilted = is_tilted(threshold);

    critical_section::with(|cs| {
        let mut tilt = TILT.borrow(cs).borrow_mut();
        // Monitoring may have stopped during the read
        if !tilt.monitoring || tilt.tilted == tilted {
            return;
        }
        tilt.tilted = tilted;
        if tilted {
            set_pattern(Priority::Tilt, Pattern::blink(color::WHITE_DIM, 500));
        } else {
            clear_pattern(Priority::Tilt);
        }
    });
}

pub fn init() {
    manager_init();
}

pub fn set_network_state(network_formed: bool) {
    if network_formed {
        // Network formed: background off, stop tilt monitoring.
        clear_pattern(Priority::Background);
        critical_section::with(|cs| {
            let mut tilt = TILT.borrow(cs).borrow_mut();
            tilt.monitoring = false;
            if core::mem::take(&mut tilt.tilted) {
                clear_pattern(Priority::Tilt);
            }
        });
    } else {
        // Searching: pulse white on the background layer, monitor tilt.
        set_pattern(Priority::Background, search_pulse(color::WHITE_DIM));
        critical_section::with(|cs| TILT.borrow(cs).borrow_mut().monitoring = true);
    }
}

/// The network search pulse in the given color, for stacks that signal search phases
pub const fn search_pulse(color: Rgb) -> Pattern {
    Pattern::pulse(color, SEARCH_PULSE_PERIOD_MS, SEARCH_PULSE_MIN_BRIGHTNESS, 65535)
}
